package com.networkers.meetingautomation;
import com.networkers.chapter.Chapter; import com.networkers.user.User; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="monthly_meeting_groups",uniqueConstraints=@UniqueConstraint(columnNames={"chapter_id","meeting_year","meeting_month","group_number"}))
public class MeetingGroup { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Chapter chapter; @Column(name="meeting_month") private int month; @Column(name="meeting_year") private int year; @Column(name="group_number") private int groupNumber; @ManyToOne(optional=false) private User host; private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public Chapter getChapter(){return chapter;} public void setChapter(Chapter v){chapter=v;} public int getMonth(){return month;} public void setMonth(int v){month=v;} public int getYear(){return year;} public void setYear(int v){year=v;} public int getGroupNumber(){return groupNumber;} public void setGroupNumber(int v){groupNumber=v;} public User getHost(){return host;} public void setHost(User v){host=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
